css:
/* =========================================================
   SALARY SLIP
   ========================================================= */

.salary-slip {
    font-family: Arial, Helvetica, sans-serif;
    font-size: 10px;
    color: #222;
    width: 100%;
    max-width: 900px;
    margin: 0 auto;
}


/* =========================================================
   HEADER
   ========================================================= */

.header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding-bottom: 10px;
    margin-bottom: 14px;
    border-bottom: 2px solid #222;
}

.company-section {
    display: flex;
    align-items: center;
    width: 65%;
}

.company-logo {
    width: 62px;
    height: 62px;
    object-fit: contain;
    margin-right: 12px;
}

.company-details {
    display: block;
}

.company-name {
    font-size: 16px;
    font-weight: 700;
    color: #222;
    margin-bottom: 4px;
}

.company-address {
    font-size: 9px;
    line-height: 1.35;
    color: #444;
}

.slip-title {
    width: 35%;
    text-align: right;
}

.salary-slip-heading {
    font-size: 16px;
    font-weight: 700;
    color: #222;
    margin-bottom: 5px;
}

.slip-number {
    font-size: 9px;
    color: #555;
}


/* =========================================================
   SECTION HEADINGS
   ========================================================= */

.section-title {
    width: 100%;
    box-sizing: border-box;
    background: #f3f3f3;
    border: 1px solid #cfcfcf;
    padding: 6px 8px;
    font-size: 10px;
    font-weight: 700;
    color: #222;
    margin-top: 10px;
}

.salary-section-title {
    margin-top: 12px;
}


/* =========================================================
   EMPLOYEE INFORMATION
   ========================================================= */

.employee-info {
    width: 100%;
    margin: 0;
    padding: 0;
    box-sizing: border-box;

    font-family: Arial, Helvetica, sans-serif;
}


/* =========================================================
   EACH EMPLOYEE ROW
   ========================================================= */

.employee-row {
    width: 100%;
    min-height: 27px;

    display: grid;

    /*
       Label  = 18%
       Value  = 32%
       Label  = 18%
       Value  = 32%
    */

    grid-template-columns: 18% 32% 18% 32%;

    align-items: center;

    box-sizing: border-box;

    border-bottom: 1px solid #dedede;
}


/* =========================================================
   LABEL
   ========================================================= */

.employee-label {
    box-sizing: border-box;

    padding: 5px 7px;

    font-size: 10px;
    line-height: 1.2;

    font-weight: 700;

    color: #222;

    text-align: left;

    white-space: nowrap;
}


/* =========================================================
   VALUE
   ========================================================= */

.employee-value {
    box-sizing: border-box;

    padding: 5px 7px;

    font-size: 10px;
    line-height: 1.2;

    font-weight: 400;

    color: #333;

    text-align: left;

    white-space: nowrap;
}


/* =========================================================
   REMOVE EXTRA SPACING
   ========================================================= */

.employee-info * {
    margin-top: 0;
    margin-bottom: 0;
}


/* =========================================================
   LAST ROW
   ========================================================= */

.employee-row:last-child {
    border-bottom: 1px solid #dedede;
}

/* =========================================================
   SALARY TABLE CONTAINER
   ========================================================= */

.salary-tables {
    width: 100%;
    display: flex;
    gap: 18px;
    align-items: flex-start;
}

.salary-column {
    width: 50%;
}


/* =========================================================
   SALARY TABLE
   ========================================================= */

.salary-table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    font-size: 10px;
    color: #222;
}


/* Table Header */

.salary-table th {
    background: #f0f0f0;
    border: 1px solid #c9c9c9;
    padding: 6px 7px;
    font-size: 10px;
    font-weight: 700;
    color: #222;
    text-align: left;
    vertical-align: middle;
}


/* Table Body */

.salary-table td {
    border: 1px solid #c9c9c9;
    padding: 6px 7px;
    font-size: 10px;
    font-weight: 400;
    color: #222;
    line-height: 1.25;
    vertical-align: middle;
}


/* Component Names */

.salary-table .component {
    font-size: 10px;
    font-weight: 400;
    color: #222;
}


/* Serial Number */

.salary-table .sr {
    width: 35px;
    text-align: center;
    font-size: 10px;
    font-weight: 400;
    color: #222;
}


/* Amount */

.salary-table .amount {
    width: 105px;
    text-align: right;
    white-space: nowrap;
    font-size: 10px;
    font-weight: 400;
    color: #222;
}


/* =========================================================
   TOTAL ROW
   ========================================================= */

.salary-table .total-row td {
    background: #fafafa;
    font-size: 10px;
    font-weight: 700;
    color: #222;
}

.salary-table .total-row .amount {
    font-weight: 700;
}


/* =========================================================
   PAYMENT SUMMARY
   ========================================================= */

.summary {
    width: 100%;
    margin-top: 14px;
    padding-top: 8px;
    border-top: 2px solid #222;
}

.summary-table {
    width: 100%;
    border-collapse: collapse;
}

.summary-table td {
    padding: 4px 7px;
    font-size: 10px;
    color: #222;
}

.summary-label {
    width: 78%;
    text-align: right;
    font-weight: 700;
}

.summary-amount {
    width: 22%;
    text-align: right;
    font-weight: 700;
    white-space: nowrap;
}


/* =========================================================
   NET PAY
   ========================================================= */

.net-pay-row td {
    border-top: 1px solid #aaa;
    border-bottom: 1px solid #aaa;
    padding-top: 6px;
    padding-bottom: 6px;
}

.net-pay-row .summary-label,
.net-pay-row .summary-amount {
    font-size: 11px;
    font-weight: 700;
}


/* =========================================================
   TOTAL IN WORDS
   ========================================================= */

.in-words {
    width: 100%;
    box-sizing: border-box;
    margin-top: 10px;
    padding: 7px 8px;
    border: 1px solid #d5d5d5;
    background: #fafafa;
    font-size: 9px;
    line-height: 1.4;
    color: #333;
}

.words-label {
    font-weight: 700;
    color: #222;
}


/* =========================================================
   FOOTER
   ========================================================= */

.footer {
    width: 100%;
    margin-top: 22px;
    padding-top: 8px;
    border-top: 1px solid #d0d0d0;
    text-align: center;
    font-size: 8px;
    color: #777;
}


/* =========================================================
   PRINT
   ========================================================= */

@media print {

    .salary-slip {
        width: 100%;
        max-width: 100%;
        margin: 0;
    }

    .header,
    .salary-tables,
    .summary,
    .employee-info {
        page-break-inside: avoid;
    }

    .salary-table {
        page-break-inside: auto;
    }

    .salary-table tr {
        page-break-inside: avoid;
    }

}
